const resolvedBeforeContinuity=shotResolvedReferences;
shotResolvedReferences=function(target){return resolvedBeforeContinuity(target).map((r,i)=>{const ref=target.continuityReference;if(i||r.type!=='scene'||!ref)return r;const item={id:ref.id,url:ref.image_url,label:ref.mode==='opening_frame'?'小七坐姿开场图':'上一镜头 '+ref.source_target_id+' 的末尾帧'};return {...r,item,choices:{...r.choices,items:[...r.choices.items.filter(v=>v.id!==item.id),item]}}})};
const shotsBeforeContinuity=shots;
shots=function(){shotsBeforeContinuity();const target=shotVideoTarget();if(!target)return;const list=data.shotScript?.hierarchical?data.shots:shotMode==='clips'?data.shotScript?.generation_clips||[]:data.shots;const index=list.indexOf(target),previous=list[index-1];const select=document.querySelector('[data-shot-ref="0"]');if(!select)return;const original=select.onchange,ref=target.continuityReference,version=previous&&selectedShotVideo(previous);if(previous){const option=document.createElement('option');option.value='__previous_tail__';option.textContent='使用上一主分镜末尾帧 · '+(previous.shot_id||previous.clip_id)+(version?.video_url?'':'（尚未生成）');option.disabled=!version?.video_url;select.append(option)}if(ref)select.value=ref.id;const note=document.createElement('p');note.className='subtle';note.textContent=ref?(ref.mode==='opening_frame'?'已使用小七坐姿开场图。':'已固定 '+ref.source_target_id+' 的末尾帧；上一镜头重生成后，可点下方按钮更新。')+' 当前为多图参考模式，参考构图，不保证像素级首帧锁定。':'可选上一主分镜的末尾帧作为场景参考，帮助衔接人物位置、构图和光线。适合同场景连续动作，切换场景时可继续用场景库。';select.after(note);
async function extract(){if(!previous)return;const selected=selectedShotVideo(previous);if(!selected?.video_url){toast('请先生成上一主分镜视频');return}select.disabled=true;try{const job=await frontFetch('/api/video-frame',{project_id:data.project_id,scene_id:ShotSchema.bindings(target)[0].ref_id,video_id:selected.id||selected.job_id});target.continuityReference=job;target.pictureSelections??={};target.pictureSelections['<Picture 1>']=job.id;save();render();toast('已提取并固定上一镜头末尾帧')}catch(e){toast(e.message);select.disabled=false}}
select.onchange=async()=>{if(select.value==='__previous_tail__')return extract();delete target.continuityReference;original?.()};if(previous){const button=document.createElement('button');button.className='wide';button.textContent=ref?'更新上一镜头末尾帧':'提取并使用上一镜头末尾帧';button.disabled=!version?.video_url;button.onclick=extract;note.after(button)}
};render();
